CREATE OR REPLACE FUNCTION public.create_reservation_intent(target_rate_plan_id uuid, target_start_at timestamp with time zone, target_guest_name text DEFAULT NULL::text, target_guest_phone text DEFAULT NULL::text, target_guest_email text DEFAULT NULL::text, target_notes text DEFAULT NULL::text)
 RETURNS reservations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare current_user_id uuid; profile_name text; profile_phone text; target_room_type_id uuid; target_hotel_id uuid; target_duration integer; target_rate_name text; target_currency text; target_price numeric; target_end_at timestamptz; selected_room_unit_id uuid; result_row public.reservations; begin current_user_id:=auth.uid(); if current_user_id is null then raise exception 'AUTH_REQUIRED'; end if; if target_start_at < now()-interval '2 minutes' then raise exception 'START_TIME_IN_PAST'; end if; select rp.room_type_id,rt.hotel_id,rp.duration_minutes,rp.name,rp.currency into target_room_type_id,target_hotel_id,target_duration,target_rate_name,target_currency from public.rate_plans rp join public.room_types rt on rt.id=rp.room_type_id join public.hotels h on h.id=rt.hotel_id where rp.id=target_rate_plan_id and rp.is_active=true and rt.is_active=true and h.approval_status='approved' and h.is_active=true; if target_room_type_id is null then raise exception 'RATE_NOT_BOOKABLE'; end if; target_end_at:=target_start_at+make_interval(mins=>target_duration); perform pg_advisory_xact_lock(hashtextextended(target_room_type_id::text,0)); select ru.id into selected_room_unit_id from public.room_units ru where ru.room_type_id=target_room_type_id and ru.is_active=true and not exists (select 1 from public.reservations r where r.room_unit_id=ru.id and r.start_at<target_end_at and r.end_at>target_start_at and (r.status in ('confirmed','checked_in') or (r.status='pending_payment' and r.payment_status='pending' and r.hold_expires_at>now()))) and not exists (select 1 from public.reservation_extensions e where e.room_unit_id=ru.id and e.status='pending_payment' and e.hold_expires_at>now() and e.original_end_at<target_end_at and e.new_end_at>target_start_at) order by ru.display_order,ru.created_at limit 1; if selected_room_unit_id is null then raise exception 'ROOM_INVENTORY_UNAVAILABLE'; end if; select full_name,phone into profile_name,profile_phone from public.profiles where id=current_user_id; target_price:=public.get_effective_rate_price(target_rate_plan_id,target_start_at); insert into public.reservations(user_id,hotel_id,room_type_id,room_unit_id,rate_plan_id,guest_name,guest_phone,guest_email,start_at,end_at,duration_minutes,rate_name,unit_price,subtotal,total_amount,currency,status,payment_status,hold_expires_at,notes) values(current_user_id,target_hotel_id,target_room_type_id,selected_room_unit_id,target_rate_plan_id,coalesce(nullif(trim(target_guest_name),''),nullif(trim(profile_name),''),'Huésped WAKI'),coalesce(nullif(trim(target_guest_phone),''),nullif(trim(profile_phone),'')),nullif(trim(target_guest_email),''),target_start_at,target_end_at,target_duration,target_rate_name,target_price,target_price,target_price,target_currency,'pending_payment','pending',now()+interval '10 minutes',nullif(trim(target_notes),'')) returning * into result_row; return result_row; end; $function$

